    if(aside&&!aside.id)aside.id='cashCartPanel';
    return aside;
  }

  function renderCashCartFast(){
    cashRemember();
    const aside=ensureCartPanelId();
    if(!aside){cashRender();annotateCashMenu();ensureCartPanelId();return}
    aside.innerHTML=cashCartHtml();
