/* rohmat-kds-horizontal-lanes-scroll-stability-v3 */
html,body{
  overscroll-behavior-y:none!important;
}
body.kdsPage{
  min-height:100dvh;
  overflow-x:hidden;
  overscroll-behavior:none!important;
}
#ordersTab{
  min-width:0;
}
.lanes{
  display:grid!important;
  grid-template-columns:repeat(3,minmax(0,1fr))!important;
  gap:10px!important;
  align-items:stretch!important;
  overflow-anchor:none;
}
.lane{
  width:100%!important;
  min-width:0!important;
  display:flex;
  flex-direction:column;
}
.cards{
  width:100%!important;
  min-width:0;
  flex:1 1 auto;
}
.empty{
  width:100%!important;
  max-width:none!important;
  min-height:82px;
  margin:0!important;
  box-sizing:border-box!important;
  display:grid;
  place-items:center;
}
@media(max-width:980px){
  .lanes{
    grid-template-columns:repeat(3,minmax(280px,1fr))!important;
    overflow-x:auto;
    overflow-y:hidden;
    overscroll-behavior-x:contain;
    scroll-snap-type:x proximity;
    scroll-behavior:auto;
    -webkit-overflow-scrolling:touch;
    scrollbar-width:thin;
    padding-bottom:8px;
  }
  .lane{
    scroll-snap-align:start;
    scroll-snap-stop:normal;
  }
}
@media(max-width:650px){
  .lanes{
    grid-template-columns:none!important;
    grid-auto-flow:column;
    grid-auto-columns:100%;
    margin-inline:0;
    padding-inline:0;
  }
  .lane{
    width:100%!important;
    max-width:100%!important;
  }
}


/* rohmat-kds-summary-lane-column-parity-v4 */
/* Surgical layout fix: summary cards and order lanes share the exact same 3-column geometry. */
.stats,
.lanes{
  display:grid!important;
  grid-template-columns:repeat(3,minmax(0,1fr))!important;
  grid-auto-flow:row!important;
  grid-auto-columns:auto!important;
  gap:10px!important;
  width:100%!important;
  max-width:100%!important;
  margin-left:0!important;
  margin-right:0!important;
  padding-left:0!important;
  padding-right:0!important;
  overflow-x:visible!important;
  overflow-y:visible!important;
  align-items:stretch!important;
}
.stats>.stat,
.lanes>.lane{
  width:100%!important;
  min-width:0!important;
  max-width:none!important;
  margin:0!important;
  box-sizing:border-box!important;
}
@media(max-width:980px){
  .stats,
  .lanes{
    grid-template-columns:repeat(3,minmax(0,1fr))!important;
    grid-auto-flow:row!important;
    grid-auto-columns:auto!important;
    overflow-x:visible!important;
    padding-bottom:0!important;
    scroll-snap-type:none!important;
  }
  .lane{
    scroll-snap-align:none!important;
  }
}
@media(max-width:650px){
  .stats,
  .lanes{
    grid-template-columns:repeat(3,minmax(0,1fr))!important;
  }
}

(()=>{'use strict';
const defaults={tenantId:'',businessName:'Business',locale:'id-ID',currency:'IDR',timezone:'Asia/Jakarta',supabaseUrl:'',publishableKey:''};
const current={...defaults};
window.__SDB_TENANT_CONFIG=current;

function apply(){
  const name=String(current.businessName||defaults.businessName);
  document.querySelectorAll('[data-tenant-business]').forEach(el=>{el.textContent=name});
  if(document.body?.classList.contains('loginPage'))document.title='Masuk KDS — '+name;
  else if(document.body?.classList.contains('kdsPage'))document.title='Kitchen Display System — '+name;
  document.documentElement.lang=String(current.locale||'id-ID').split('-')[0]||'id';
  document.dispatchEvent(new CustomEvent('sdb:tenant-config',{detail:{...current}}));
}

window.__SDB_TENANT_CONFIG_READY=(async()=>{
  try{
    const r=await fetch('/api/config',{cache:'no-store',credentials:'same-origin'});
    if(r.ok){
      const n=await r.json();
      for(const k of Object.keys(defaults))if(n?.[k]!=null&&String(n[k]).trim())current[k]=n[k];
    }
  }catch{}
  apply();
  return current;
})();
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',apply,{once:true});else apply();
})();

(() => {
  const style = document.createElement('style');
  style.textContent = `
    #cashierRoot .cashTop > div:first-child{display:none!important}
    #cashierRoot .cashTop{justify-content:flex-end!important;margin-bottom:8px!important}
    #cashierRoot .cashItem{position:relative}
    #cashierRoot .cashItemQty{
      position:absolute;top:14px;right:14px;z-index:4;
      min-width:30px;height:30px;padding:0 8px;border-radius:999px;
      display:grid;place-items:center;background:#264b3e;color:#fff;
      border:2px solid #fff;font-weight:950;font-size:13px;
      box-shadow:0 2px 8px rgba(0,0,0,.18)
    }
    #cashierRoot .cashItemQty[hidden]{display:none!important}
  `;
  document.head.appendChild(style);

  function syncMenuQuantities(){
    document.querySelectorAll('#cashierRoot [data-cash-add]').forEach(btn => {
      const id = String(btn.dataset.cashAdd || '');
      const qty = Math.max(0, Number(cart?.[id] || 0));
      const item = btn.closest('.cashItem');
      if (!item) return;

      let badge = item.querySelector('.cashItemQty');
      if (!badge) {
        badge = document.createElement('span');
        badge.className = 'cashItemQty';
        badge.setAttribute('aria-live','polite');
        item.appendChild(badge);
      }
      badge.textContent = String(qty);
      badge.hidden = qty < 1;

      btn.textContent = qty > 0 ? `+ Tambah · ${qty}` : '+ Tambah';
      btn.setAttribute('aria-label', qty > 0 ? `Tambah lagi, jumlah saat ini ${qty}` : 'Tambah menu');
    });
  }

  function tidyCashierHeader(){
    const top = document.querySelector('#cashierRoot .cashTop');
    if (!top) return;
    const intro = top.querySelector(':scope > div:first-child');
    if (intro) intro.hidden = true;
  }

  const baseCashRender = cashRender;
  cashRender = function(){
    baseCashRender();
    tidyCashierHeader();
    syncMenuQuantities();
  };

  const baseCashBind = cashBind;
  cashBind = function(){
    baseCashBind();
    tidyCashierHeader();
    syncMenuQuantities();
  };

  const baseCashRerender = cashRerender;
  cashRerender = function(fn){
    baseCashRerender(fn);
    queueMicrotask(() => {
      tidyCashierHeader();
      syncMenuQuantities();
    });
  };

  const observer = new MutationObserver(() => {
    tidyCashierHeader();
    syncMenuQuantities();
  });
  const root = document.getElementById('cashierRoot');
  if (root) observer.observe(root,{childList:true,subtree:true});

  queueMicrotask(() => {
    tidyCashierHeader();
    syncMenuQuantities();
  });
})();

