async function getRuntime(upstream) {
  const now = Date.now();
  const cached = memo.get(upstream);
  if (cached && now - cached.at < CACHE_MS) return cached.body;
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 2500);
  try {
    const response = await fetch(upstream, { cache: 'no-store', signal: controller.signal });
    if (!response.ok) throw new Error(`upstream_${response.status}`);
    const raw = await response.text();
    const mode = String(response.headers.get('x-rohmat-runtime-mode') || '').toLowerCase();
    if (mode === 'rum-only') {
      if (raw.length < 5000 || !raw.includes('__rohmatRumV3') || !raw.includes("rohmatRuntime='rum-only-batch1-v1'")) throw new Error('upstream_rum_invalid');
      memo.set(upstream, { body: raw, at: now });
      if (memo.size > 8) memo.delete(memo.keys().next().value);
      return raw;
    }
    if (raw.length < 40000 || !raw.includes('__rohmatPublicUXV17') || !raw.includes('__rohmatPublicDesignV24')) throw new Error('upstream_invalid');
    const optimized = optimizeLifecycle(raw);
    memo.set(upstream, { body: optimized.body, at: now });
    if (memo.size > 8) memo.delete(memo.keys().next().value);
    return optimized.body;
  } finally {
    clearTimeout(timer);
  }
}

export default async function handler(req, res) {
  if (req.method !== 'GET' && req.method !== 'HEAD') {
    res.statusCode = 405;
    res.setHeader('Allow', 'GET, HEAD');
    return res.end('Method Not Allowed');
  }
  try {
    const upstream = readUpstream(req);
    const body = await getRuntime(upstream);
    res.statusCode = 200;
    res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
    res.setHeader('Cache-Control', 'public, max-age=30, s-maxage=30, stale-while-revalidate=30');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    res.setHeader('Cross-Origin-Resource-Policy', 'same-origin');
    res.setHeader('X-Rohmat-Runtime', 'v68-origin-bound+canonical-fallback+lifecycle-or-rum');
    res.setHeader('X-Rohmat-Lifecycle', 'dialog-observer-owner+design-poll-pause-pagehide-bfcache');
    if (req.method === 'HEAD') return res.end();
    return res.end(body);
  } catch (error) {
    console.error('[runtime-lifecycle-503]', JSON.stringify({status:503,error:String(error?.message || error).slice(0,160)}));
    res.statusCode = 503;
    res.setHeader('Content-Type', 'application/javascript; charset=utf-8');
    res.setHeader('Cache-Control', 'no-store');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    return res.end(`/* lifecycle runtime unavailable: ${String(error?.message || error)} */`);
  }
}

const FALLBACK = Object.freeze({
  locale: 'id-ID',
  cuisine: 'Food & Beverage'
});

function clean(value, fallback, max = 180) {
  const v = String(value || '').trim();
  return v ? v.slice(0, max) : fallback;
}

function origin(value) {
  try {
    const u = new URL(String(value || '').trim());
    if (u.protocol !== 'https:' || u.username || u.password) throw new Error('https_required');
    return u.origin;
  } catch {
    return '';
  }
}

function absoluteHttps(value) {
  try {
    const u = new URL(String(value || '').trim());
    if (u.protocol !== 'https:' || u.username || u.password) throw new Error('https_required');
    return u.href;
  } catch {
    return '';
  }
}

export function getPublicTenantConfig(env = process.env) {
  const strict = env.MASTER_PROTOTYPE_STRICT === '1' || env.MASTER_CLONE_STRICT === '1';
  const required = ['SDB_TENANT_ID','PUBLIC_ORIGIN','BUSINESS_NAME'];
  const missing = required.filter(key => !String(env[key] || '').trim());
  const tenantId = clean(env.SDB_TENANT_ID, '', 64);
  const businessName = clean(env.BUSINESS_NAME, 'Business', 100);
  const publicOrigin = origin(env.PUBLIC_ORIGIN);
  if (!publicOrigin && !missing.includes('PUBLIC_ORIGIN')) missing.push('PUBLIC_ORIGIN');
  const locale = clean(env.TENANT_LOCALE, FALLBACK.locale, 32);
  const description = clean(
    env.PUBLIC_DESCRIPTION,
    `Pesan menu ${businessName} secara online dengan cepat, praktis, dan aman.`,
    220
  );
  const cuisine = clean(env.PUBLIC_CUISINE, FALLBACK.cuisine, 80);
  return {
    tenantId,
    ok: missing.length === 0,
    missing,
    strict,
    origin: publicOrigin,
    canonical: publicOrigin + '/',
    businessName,
    title: `${businessName} — Pesan & Bayar`,
    description,
    locale,
    ogLocale: locale.replace('-', '_'),
    cuisine,
    socialImage: publicOrigin + '/og-image.png',
    heroImageUrl: absoluteHttps(env.HERO_IMAGE_URL)
  };
}

export function failTenantConfig(res, missing = []) {
  res.statusCode = 503;
  res.setHeader('Content-Type', 'text/plain; charset=utf-8');
  res.setHeader('Cache-Control', 'no-store');
  return res.end('tenant_configuration_incomplete' + (missing.length ? ':' + missing.join(',') : ''));
}

export function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>"']/g, ch => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[ch]));
}


function requestOrigin(req) {
  const proto = String(req?.headers?.['x-forwarded-proto'] || 'https').split(',')[0].trim().toLowerCase();
  const host = String(req?.headers?.['x-forwarded-host'] || req?.headers?.host || '').split(',')[0].trim().toLowerCase();
  if (proto !== 'https' || !host || !/^[a-z0-9.-]+(?::\d{1,5})?$/.test(host)) return '';
  return 'https://' + host;
}

export async function resolvePublicTenantConfig(req, env = process.env) {
  const direct = getPublicTenantConfig(env);
  const supabaseUrl = origin(env.SUPABASE_URL);
  const publishableKey = clean(env.SUPABASE_PUBLISHABLE_KEY || env.SUPABASE_ANON_KEY, '', 500);
  const requestedOrigin = requestOrigin(req);
  if (!supabaseUrl || !publishableKey || !requestedOrigin) {
    if (direct.ok && direct.tenantId) return direct;
    return { ...direct, ok:false, missing:[...new Set([...(direct.missing||[]), !publishableKey?'SUPABASE_PUBLISHABLE_KEY':'', !requestedOrigin?'REQUEST_ORIGIN':''].filter(Boolean))] };
  }

  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 1800);
    let response;
    try {
      response = await fetch(supabaseUrl + '/rest/v1/rpc/master_prototype_resolve_origin', {
        method:'POST',
        cache:'no-store',
        signal:controller.signal,
        headers:{
          apikey:publishableKey,
          Authorization:'Bearer ' + publishableKey,
          'Content-Type':'application/json'
        },
        body:JSON.stringify({ p_origin:requestedOrigin, p_app_kind:'public' })
      });
    } finally {
      clearTimeout(timer);
    }
    const resolved = await response.json().catch(() => null);
    if (!response.ok || !resolved?.ok || !resolved?.tenant_id || !resolved?.business_name) {
      return { ...direct, ok:false, missing:['TENANT_ORIGIN_MAPPING'] };
    }
    const canonicalOrigin = origin(resolved.public_origin) || requestedOrigin;
    const locale = clean(resolved.locale, FALLBACK.locale, 32);
    const businessName = clean(resolved.business_name, 'Business', 100);
    const description = clean(
      env.PUBLIC_DESCRIPTION,
      `Pesan menu ${businessName} secara online dengan cepat, praktis, dan aman.`,
      220
    );
    const cuisine = clean(env.PUBLIC_CUISINE, FALLBACK.cuisine, 80);
    return {
      tenantId:String(resolved.tenant_id),
      tenantSlug:String(resolved.tenant_slug||''),
      ok:true,
      missing:[],
      strict:true,
      origin:canonicalOrigin,
      requestOrigin:requestedOrigin,
      canonical:canonicalOrigin + '/',
      businessName,
      title:`${businessName} — Pesan & Bayar`,
      description,
      locale,
      ogLocale:locale.replace('-', '_'),
      cuisine,
      socialImage:canonicalOrigin + '/og-image.png',
      heroImageUrl:absoluteHttps(resolved.hero_image_url),
      resolvedBy:'origin'
    };
  } catch {
    if (direct.ok && direct.tenantId) return { ...direct, resolvedBy:'environment-fallback' };
    return { ...direct, ok:false, missing:['TENANT_ORIGIN_RESOLUTION'] };
  }
}

{
  "$schema": "https://openapi.vercel.sh/vercel.json",
  "ignoreCommand": "git diff --name-only HEAD^ HEAD | grep -Eq '^(apps/public/|package.json$|package-lock.json$|pnpm-lock.yaml$|yarn.lock$)' && exit 1 || exit 0",
  "rewrites": [
    { "source": "/robots.txt", "destination": "/api/robots" },
    { "source": "/sitemap.xml", "destination": "/api/sitemap" },
    { "source": "/manifest.webmanifest", "destination": "/api/manifest" },
    { "source": "/favicon.ico", "destination": "/api/brand-assets?kind=favicon" },
    { "source": "/apple-touch-icon.png", "destination": "/api/brand-assets?kind=apple" },
    { "source": "/icon-192.png", "destination": "/api/brand-assets?kind=icon192" },
    { "source": "/icon-512.png", "destination": "/api/brand-assets?kind=icon512" },
    { "source": "/og-image.png", "destination": "/api/brand-assets?kind=og" },
    { "source": "/ocr-worker.js", "destination": "/api/ocr-worker" },
    { "source": "/runtime-lifecycle.js", "destination": "/api/render-seo-brand?rohmat_runtime=lifecycle" },
    { "source": "/(.*)", "destination": "/api/render-seo-brand" }
  ],
  "headers": [
    {
      "source": "/(.*)",
      "headers": [
        { "key": "Strict-Transport-Security", "value": "max-age=63072000; includeSubDomains; preload" },
        { "key": "X-Content-Type-Options", "value": "nosniff" },
        { "key": "X-Frame-Options", "value": "DENY" },
        { "key": "Referrer-Policy", "value": "no-referrer" },
        { "key": "Permissions-Policy", "value": "camera=(), microphone=(), geolocation=(), payment=(), usb=(), serial=()" },
        { "key": "X-Permitted-Cross-Domain-Policies", "value": "none" }
      ]
    }
  ]
}

